          {showNote&&<View style={s.field}><Text style={s.label}>Note (optional)</Text><TextInput value={note} onChangeText={setNote} multiline placeholder="Write a note for this sale" placeholderTextColor={colors.muted} style={s.noteInput}/></View>}
